@router.get("/workspaces/{workspace_id}/cad-models/{model_id}")
async def get_cad_model(
    workspace_id: str,
    model_id: PydanticObjectId,
    current_user: User = Depends(get_current_user)
):
    if workspace_id not in current_user.accessible_workspaces:
        raise HTTPException(status_code=403, detail="Forbidden: access to workspace denied")

    model_doc = await CADModelDocument.find_one(
        CADModelDocument.id == model_id,
        CADModelDocument.workspace_id == workspace_id,
        fetch_links=True
    )
    if not model_doc:
        raise HTTPException(status_code=404, detail="CAD Model not found in this workspace")

    return {
        "model_id": str(model_doc.id),
        "title": model_doc.title,
        "mesh_url": model_doc.mesh_s3_url,
        "revisions": [r.version_tag for r in model_doc.revisions]
    }
